import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
targets = json.loads(Path('reference-targets.json').read_text())
drafts = {}


def put(number, paragraphs, reason, notes, removed=None, repeal=None, benefit=None):
    source = next(s for s in sources if s['number'] == number)
    item = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(proposed_xml=''.join('<p>' + p.strip() + '</p>' for p in paragraphs.strip().split('\n') if p.strip()),
                reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        item.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        item.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if benefit:
        item['benefit_review'] = benefit
    drafts[number] = item


